{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\nuse std::io::{self, Write};\\r\\n\\r\\nuse nu_ansi_term::AnsiStrings as ANSIStrings;\\r\\n\\r\\nuse crate::fs::filter::FileFilter;\\r\\nuse crate::fs::File;\\r\\nuse crate::output::cell::TextCellContents;\\r\\nuse crate::output::file_name::Options as FileStyle;\\r\\nuse crate::theme::Theme;\\r\\n\\r\\n/// The lines view literally just displays each file, line-by-line.\\r\\npub struct Render<'a> {\\r\\n    pub files: Vec<File<'a>>,\\r\\n    pub theme: &'a Theme,\\r\\n    pub file_style: &'a FileStyle,\\r\\n    pub filter: &'a FileFilter,\\r\\n}\\r\\n\\r\\nimpl<'a> Render<'a> {\\r\\n    pub fn render<W: Write>(mut self, w: &mut W) -> io::Result<()> {\\r\\n        self.filter.sort_files(&mut self.files);\\r\\n        for file in &self.files {\\r\\n            let name_cell = self.render_file(file);\\r\\n            writeln!(w, \\\"{}\\\", ANSIStrings(&name_cell))?;\\r\\n        }\\r\\n\\r\\n        Ok(())\\r\\n    }\\r\\n\\r\\n    fn render_file<'f>(&self, file: &'f File<'a>) -> TextCellContents {\\r\\n        self.file_style\\r\\n            .for_file(file, self.theme)\\r\\n            .with_link_paths()\\r\\n            .with_mount_details(false)\\r\\n            .paint()\\r\\n    }\\r\\n}\\r\\n\\r\\n\"}","command":"shell_command","command_index":1,"command_line":"{\"command\":\"Get-Content -Raw rust-reference\\\\src\\\\output\\\\lines.rs\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\blog_data\\\\eza-replication-gpt56-max-20260717\\\\project-rebuild-source-port\\\\r-f265dec58c\\\\eza\\\\balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c30a370549cf4c.tool.command_run:call_oD