{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\n//! Timestamp formatting.\\r\\n\\r\\nuse chrono::prelude::*;\\r\\nuse core::cmp::max;\\r\\nuse std::sync::LazyLock;\\r\\nuse std::time::Duration;\\r\\nuse unicode_width::UnicodeWidthStr;\\r\\n\\r\\n/// Every timestamp in exa needs to be rendered by a **time format**.\\r\\n/// Formatting times is tricky, because how a timestamp is rendered can\\r\\n/// depend on one or more of the following:\\r\\n///\\r\\n/// - The user’s locale, for printing the month name as “Feb”, or as “fév”,\\r\\n///   or as “2月”;\\r\\n/// - The current year, because certain formats will be less precise when\\r\\n///   dealing with dates far in the past;\\r\\n/// - The formatting style that the user asked for on the command-line.\\r\\n///\\r\\n/// Because not all formatting styles need the same data, they all have their\\r\\n/// own enum variants. It’s not worth looking the locale up if the formatter\\r\\n/// prints month names as numbers.\\r\\n///\\r\\n/// Also, eza supports *custom* styles, where the user enters a\\r\\n/// format string in an environment variable or something. Just these four.\\r\\n#[derive(PartialEq, Eq, Debug, Clone)]\\r\\npub enum TimeFormat {\\r\\n    /// The **default format** uses the user’s locale to print month names,\\r\\n    /// and specifies the timestamp down to the minute for recent times, and\\r\\n    /// day for older times.\\r\\n    DefaultFormat,\\r\\n\\r\\n    /// Use the **ISO format**, which specifies the timestamp down to the\\r\\n    /// minute for recent times, and day for older times. It uses a number\\r\\n    /// for the month so it doesn’t use the locale.\\r\\n    ISOFormat,\\r\\n\\r\\n    /// Use the **long ISO format**, which specifies the timestamp down to the\\r\\n    /// minute using only numbers, without needing the locale or year.\\r\\n    LongISO,\\r\\n\\r\\n    /// Use the **full ISO format**, which specifies the timestamp down to the\\r\\n    /// millisecond and includes its offset down to the minute. This too uses\\r\\n    /// only numbers so doesn’t require any special consideration.\\r\\n    FullISO,\\r\\n\\r\\n    /// Use a relative but fixed width representation.\\r\\n    Relative,\\r\\n\\r\\n    /// Use custom formats, optionally a different custom format can be\\r\\n    /// specified for recent times, otherwise the same custom format will be\\r\\n    /// used for both recent and non-recent times.\\r\\n    Custom {\\r\\n        non_recent: String,\\r\\n        recent: Option<String>,\\r\\n    },\\r\\n}\\r\\n\\r\\nimpl TimeFormat {\\r\\n    #[must_use]\\r\\n    pub fn format(self, time: &DateTime<FixedOffset>) -> String {\\r\\n        #[rustfmt::skip]\\r\\n        return match self {\\r\\n            Self::DefaultFormat                 => default(time),\\r\\n            Self::ISOFormat                     => iso(time),\\r\\n            Self::LongISO                       => long(time),\\r\\n            Self::FullISO                       => full(time),\\r\\n            Self::Relative                      => relative(time),\\r\\n            Self::Custom { non_recent, recent } => custom(\\r\\n                time, non_recent.as_str(), recent.as_deref()\\r\\n            ),\\r\\n        };\\r\\n    }\\r\\n}\\r\\n\\r\\nfn default(time: &DateTime<FixedOffset>) -> String {\\r\\n    let month = &*LOCALE.short_month_name(time.month0() as usize);\\r\\n    let month_width = short_month_padding(*MAX_MONTH_WIDTH, month);\\r\\n    let format = if time.year() == *CURRENT_YEAR {\\r\\n        format!(\\\"%_d {month:<month_width$} %H:%M\\\")\\r\\n    } else {\\r\\n        format!(\\\"%_d {month:<month_width$}  %Y\\\")\\r\\n    };\\r\\n    time.format(format.as_str()).to_string()\\r\\n}\\r\\n\\r\\n/// Convert between Unicode width and width in chars to use in format!.\\r\\n/// ex: in Japanese, 月 is one character, but it has the width of two.\\r\\n/// For alignment purposes, we take the real display width into account.\\r\\n/// So, `MAXIMUM_MONTH_WIDTH` (“12月”) = 4, but if we use `{:4}` in format!,\\r\\n/// it will add a space (“ 12月”) because format! counts characters.\\r\\n/// Conversely, a char can have a width of zero (like combining diacritics)\\r\\nfn short_month_padding(max_month_width: usize, month: &str) -> usize {\\r\\n    let shift = month.chars().count() as isize - UnicodeWidthStr::width(month) as isize;\\r\\n    (max_month_width as isize + shift) as usize\\r\\n}\\r\\n\\r\\nfn iso(time: &DateTime<FixedOffset>) -> String {\\r\\n    if time.year() == *CURRENT_YEAR {\\r\\n        time.format(\\\"%m-%d %H:%M\\\").to_string()\\r\\n    } else {\\r\\n        time.format(\\\"%Y-%m-%d\\\").to_string()\\r\\n    }\\r\\n}\\r\\n\\r\\nfn long(time: &DateTime<FixedOffset>) -> String {\\r\\n    time.format(\\\"%Y-%m-%d %H:%M\\\").to_string()\\r\\n}\\r\\n\\r\\n// #[allow(trivial_numeric_casts)]\\r\\nfn relative(time: &DateTime<FixedOffset>) -> String {\\r\\n    timeago::Formatter::new()\\r\\n        .ago(\\\"\\\")\\r\\n        .convert(Duration::from_secs(\\r\\n            max(0, Local::now().timestamp() - time.timestamp())\\r\\n                // this .unwrap is safe since the call above can never result in a\\r\\n                // value < 0\\r\\n                .try_into()\\r\\n                .unwrap(),\\r\\n        ))\\r\\n}\\r\\n\\r\\nfn full(time: &DateTime<FixedOffset>) -> String {\\r\\n    time.format(\\\"%Y-%m-%d %H:%M:%S.%f %z\\\").to_string()\\r\\n}\\r\\n\\r\\nfn custom(time: &DateTime<FixedOffset>, non_recent_fmt: &str, recent_fmt: Option<&str>) -> String {\\r\\n    if let Some(recent_fmt) = recent_fmt {\\r\\n        if time.year() == *CURRENT_YEAR {\\r\\n            time.format(recent_fmt).to_string()\\r\\n        } else {\\r\\n            time.format(non_recent_fmt).to_string()\\r\\n        }\\r\\n    } else {\\r\\n        time.format(non_recent_fmt).to_string()\\r\\n    }\\r\\n}\\r\\n\\r\\nstatic CURRENT_YEAR: LazyLock<i32> = LazyLock::new(|| Local::now().year());\\r\\n\\r\\nstatic LOCALE: LazyLock<locale::Time> =\\r\\n    LazyLock::new(|| locale::Time::load_user_locale().unwrap_or_else(|_| locale::Time::english()));\\r\\n\\r\\nstatic MAX_MONTH_WIDTH: LazyLock<usize> = LazyLock::new(|| {\\r\\n    // Some locales use a three-character wide month name (Jan to Dec);\\r\\n    // others vary between three to four (1月 to 12月, juil.). We check each month width\\r\\n    // to detect the longest and set the output format accordingly.\\r\\n    (0..11)\\r\\n        .map(|i| UnicodeWidthStr::width(&*LOCALE.short_month_name(i)))\\r\\n        .max()\\r\\n        .unwrap()\\r\\n});\\r\\n\\r\\n#[cfg(test)]\\r\\nmod test {\\r\\n    use super::*;\\r\\n\\r\\n    #[test]\\r\\n    fn short_month_width_japanese() {\\r\\n        let max_month_width = 4;\\r\\n        let month = \\\"1\\\\u{2F49}\\\"; // 1月\\r\\n        let padding = short_month_padding(max_month_width, month);\\r\\n        let final_str = format!(\\\"{month:<padding$}\\\");\\r\\n        assert_eq!(max_month_width, UnicodeWidthStr::width(final_str.as_str()));\\r\\n    }\\r\\n\\r\\n    #[test]\\r\\n    fn short_month_width_hindi() {\\r\\n        let max_month_width = 4;\\r\\n        assert!([\\r\\n            \\\"\\\\u{091C}\\\\u{0928}\\\\u{0970}\\\",                         // जन॰\\r\\n            \\\"\\\\u{092B}\\\\u{093C}\\\\u{0930}\\\\u{0970}\\\",                 // फ़र॰\\r\\n            \\\"\\\\u{092E}\\\\u{093E}\\\\u{0930}\\\\u{094D}\\\\u{091A}\\\",         // मार्च\\r\\n            \\\"\\\\u{0905}\\\\u{092A}\\\\u{094D}\\\\u{0930}\\\\u{0948}\\\\u{0932}\\\", // अप्रैल\\r\\n            \\\"\\\\u{092E}\\\\u{0908}\\\",                                 // मई\\r\\n            \\\"\\\\u{091C}\\\\u{0942}\\\\u{0928}\\\",                         // जून\\r\\n            \\\"\\\\u{091C}\\\\u{0941}\\\\u{0932}\\\\u{0970}\\\",                 // जुल॰\\r\\n            \\\"\\\\u{0905}\\\\u{0917}\\\\u{0970}\\\",                         // अग॰\\r\\n            \\\"\\\\u{0938}\\\\u{093F}\\\\u{0924}\\\\u{0970}\\\",                 // सित॰\\r\\n            \\\"\\\\u{0905}\\\\u{0915}\\\\u{094D}\\\\u{0924}\\\\u{0942}\\\\u{0970}\\\", // अक्तू॰\\r\\n            \\\"\\\\u{0928}\\\\u{0935}\\\\u{0970}\\\",                         // नव॰\\r\\n            \\\"\\\\u{0926}\\\\u{093F}\\\\u{0938}\\\\u{0970}\\\",                 // दिस॰\\r\\n        ]\\r\\n        .iter()\\r\\n        .map(|month| format!(\\r\\n            \\\"{:<width$}\\\",\\r\\n            month,\\r\\n            width = short_month_padding(max_month_width, month)\\r\\n        ))\\r\\n        .all(|string| UnicodeWidthStr::width(string.as_str()) == max_month_width));\\r\\n    }\\r\\n}\\r\\n\\r\\n\"}","command":"shell_command","command_index":5,"command_line":"{\"command\":\"Get-Content -Raw rust-reference\\\\src\\\\output\\\\time.rs\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\blog_data\\\\eza-replication-gpt56-max-20260717\\\\project-rebuild-source-port\\\\r-f265dec58c\\\\eza\\\\balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c30a370549cf4c.tool.command_run:call_oD9kYdEveqvVR21Tel12PndU:5","provider_tool_call_id":"call_oD9kYdEveqvVR21Tel12PndU","status":"completed","step":1,"type":"command_execution"},"type":"item.completed"}
{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"Total output lines: 291\\n\\nTotal output lines: 538\\n\\n// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\nuse std::fmt::Debug;\\r\\nuse std::path::Path;\\r\\n\\r\\nuse nu_ansi_term::{AnsiString as ANSIString, Style};\\r\\nuse path_clean;\\r\\nuse unicode_width::UnicodeWidthStr;\\r\\n\\r\\nuse crate::fs::{File, FileTarget};\\r\\nuse crate::output::cell::TextCellContents;\\r\\nuse crate::output::escape;\\r\\nuse crate::output::icons::{icon_for_file, iconify_style};\\r\\nuse crate::output::render::FiletypeColours;\\r\\nuse crate::theme::FileNameStyle;\\r\\n\\r\\n/// Basically a file name factory.\\r\\n#[derive(Debug, Copy, Clone)]\\r\\npub struct Options {\\r\\n    /// Whether to append file class characters to file names.\\r\\n    pub classify: Classify,\\r\\n\\r\\n    /// Whether to prepend icon characters before file names.\\r\\n    pub show_icons: ShowIcons,\\r\\n\\r\\n    /// How to display file names with spaces (with or without quotes).\\r\\n    pub quote_style: QuoteStyle,\\r\\n\\r\\n    /// Whether to make file names hyperlinks.\\r\\n    pub embed_hyperlinks: EmbedHyperlinks,\\r\\n\\r\\n    /// Whether to display files with their absolute path.\\r\\n    pub absolute: Absolute,\\r\\n\\r\\n    /// Whether we are in a console or redirecting the output\\r\\n    pub is_a_tty: bool,\\r\\n}\\r\\n\\r\\nimpl Options {\\r\\n    /// Create a new `FileName` that prints the given file’s name, painting it\\r\\n    /// with the remaining arguments.\\r\\n    pub fn for_file<'a, 'dir, C>(\\r\\n        self,\\r\\n        file: &'a File<'dir>,\\r\\n        colours: &'a C,\\r\\n    ) -> FileName<'a, 'dir, C> {\\r\\n        FileName {\\r\\n            file,\\r\\n            colours,\\r\\n            link_style: LinkStyle::JustFilenames,\\r\\n            options: self,\\r\\n            target: if file.is_link() {\\r\\n                Some(file.link_target())\\r\\n            } else {\\r\\n                None\\r\\n            },\\r\\n            mount_style: MountStyle::JustDirectoryNames,\\r\\n        }\\r\\n    }\\r\\n}\\r\\n\\r\\n/// When displaying a file name, there needs to be some way to handle broken\\r\\n/// links, depending on how long the resulting Cell can be.\\r\\n#[derive(PartialEq, Debug, Copy, Clone)]\\r\\nenum LinkStyle {\\r\\n    /// Just display the file names, but colour them differently if they’re\\r\\n    /// a broken link or can’t be followed.\\r\\n    JustFilenames,\\r\\n\\r\\n    /// Display all files in their usual style, but follow each link with an\\r\\n    /// arrow pointing to their path, colouring the path differently if it’s\\r\\n    /// a broken link, and doing nothing if it can’t be followed.\\r\\n    FullLinkPaths,\\r\\n}\\r\\n\\r\\n/// Whether to append file class characters to the file names.\\r\\n#[derive(PartialEq, Eq, Debug, Default, Copy, Clone)]\\r\\npub enum Classify {\\r\\n    /// Just display the file names, without any characters.\\r\\n    #[default]\\r\\n    JustFilenames,\\r\\n\\r\\n    /// Always add a character after the file name depending on what class of\\r\\n    /// file it is.\\r\\n    AddFileIndicators,\\r\\n\\r\\n    // Like previous, but only when output is going to a terminal, not otherwise.\\r\\n    AutomaticAddFileIndicators,\\r\\n}\\r\\n\\r\\n/// When displaying a directory name, there needs to be some way to handle\\r\\n/// mount details, depending on how long the resulting Cell can be.\\r\\n#[derive(PartialEq, Debug, Copy, Clone)]\\r\\nenum MountStyle {\\r\\n    /// Just display the directory names.\\r\\n    JustDirectoryNames,\\r\\n\\r\\n    /// Display mount points as directories and include information about\\r\\n    /// the filesystem that's mounted there.\\r\\n    MountInfo,\\r\\n}\\r\\n\\r\\n/// Whether and how to show icons.\\r\\n#[derive(PartialEq, Debug, Copy, Clone)]\\r\\npub enum ShowIcons {\\r\\n    /// Display icons next to file names, with the given number of spaces between\\r\\n    /// the icon and the file name, even when output isn’t going to a terminal.\\r\\n    Always(u32),\\r\\n\\r\\n    /// Same as Always, but only when output is going to a terminal, not otherwise.\\r\\n    Automatic(u32),\\r\\n\\r\\n    /// Never display them, even when output is going to a terminal.\\r\\n    Never,\\r\\n}\\r\\n\\r\\n/// Whether to embed hyperlinks.\\r\\n#[derive(PartialEq, Eq, Debug, Copy, Clone)]\\r\\npub enum EmbedHyperlinks {\\r\\n    Off,\\r\\n    On,\\r\\n}\\r\\n\\r\\n/// Whether to show absolute paths\\r\\n#[derive(PartialEq, Eq, Debug, Copy, Clone)]\\r\\npub enum Absolute {\\r\\n    On,\\r\\n    Follow,\\r\\n    Off,\\r\\n}\\r\\n\\r\\n/// Whether or not to wrap file names with spaces in quotes.\\r\\n#[derive(PartialEq, Debug, Copy, Clone)]\\r\\npub enum QuoteStyle {\\r\\n    /// Don't ever quote file names.\\r\\n    NoQuotes,\\r\\n\\r\\n    /// Use single quotes for file names that contain spaces and no single quotes\\r\\n    /// Use double quotes for file names that contain single quotes.\\r\\n    QuoteSpaces,\\r\\n}\\r\\n\\r\\n/// A **file name** holds all the information necessary to display the name\\r\\n/// of the given file. This is used in all of the views.\\r\\npub struct FileName<'a, 'dir, C> {\\r\\n    /// A reference to the file that we’re getting the name of.\\r\\n    file: &'a File<'dir>,\\r\\n\\r\\n    /// The colours used to paint the file name and its surrounding text.\\r\\n    colours: &'a C,\\r\\n\\r\\n    /// The file that this file points to if it...58 characters truncated...e’ll be newlines in weird places.\\r\\n    ///\\r\\n    /// So in that situation, those characters will be escaped and highlighted in\\r\\n    /// a different colour.\\r\\n    fn escaped_file_name<'unused>(\\r\\n        &self,\\r\\n        style_override: Option<Style>,\\r\\n    ) -> Vec<ANSIString<'unused>> {\\r\\n        let file_style = style_override.unwrap_or(self.style());\\r\\n        let mut bits = Vec::new();\\r\\n\\r\\n        let mut display_hyperlink = false;\\r\\n        if self.options.embed_hyperlinks == EmbedHyperlinks::On {\\r\\n            if let Some(abs_path) = self\\r\\n                .file\\r\\n                .absolute_path()\\r\\n                .and_then(|p| p.as_os_str().to_str())\\r\\n            {\\r\\n                bits.push(ANSIString::from(escape::get_hyperlink_start_tag(abs_path)));\\r\\n\\r\\n                display_hyperlink = true;\\r\\n            }\\r\\n        }\\r\\n\\r\\n        escape(\\r\\n            self.display_name(),\\r\\n            &mut bits,\\r\\n            file_style,\\r\\n            self.colours.control_char(),\\r\\n            self.options.quote_style,\\r\\n        );\\r\\n\\r\\n        if display_hyperlink {\\r\\n            bits.push(ANSIString::from(escape::HYPERLINK_CLOSING));\\r\\n        }\\r\\n\\r\\n        bits\\r\\n    }\\r\\n\\r\\n    /// Returns the string that should be displayed as the file's name.\\r\\n    fn display_name(&self) -> String {\\r\\n        match self.options.absolute {\\r\\n            Absolute::On => std::env::current_dir().ok().and_then(|p| {\\r\\n                path_clean::clean(p.join(&self.file.path))\\r\\n                    .to_str()\\r\\n                    .map(std::borrow::ToOwned::to_owned)\\r\\n            }),\\r\\n            Absolute::Follow => self\\r\\n                .file\\r\\n                .absolute_path()\\r\\n                .and_then(|p| p.to_str())\\r\\n                .map(std::borrow::ToOwned::to_owned),\\r\\n            Absolute::Off => None,\\r\\n        }\\r\\n        .unwrap_or(self.file.name.clone())\\r\\n    }\\r\\n\\r\\n    /// Figures out which colour to paint the filename part of the output,\\r\\n    /// depending on which “type” of file it appears to be — either from the\\r\\n    /// class on the filesystem or from its name. (Or the broken link colour,\\r\\n    /// if there’s nowhere else for that fact to be shown.)\\r\\n    #[must_use]\\r\\n    pub fn style(&self) -> Style {\\r\\n        if let LinkStyle::JustFilenames = self.link_style {\\r\\n            if let Some(ref target) = self.target {\\r\\n                if target.is_broken() {\\r\\n                    return self.colours.broken_symlink();\\r\\n                }\\r\\n            }\\r\\n        }\\r\\n\\r\\n        #[rustfmt::skip]\\r\\n        return match self.file {\\r\\n            f if f.is_mount_point()      => self.colours.mount_point(),\\r\\n            f if f.is_directory()        => self.colours.directory(),\\r\\n            #[cfg(unix)]\\r\\n            f if f.is_executable_file()  => self.colours.executable_file(),\\r\\n            f if f.is_link()             => self.colours.symlink(),\\r\\n            #[cfg(unix)]\\r\\n            f if f.is_pipe()             => self.colours.pipe(),\\r\\n            #[cfg(unix)]\\r\\n            f if f.is_block_device()     => self.colours.block_device(),\\r\\n            #[cfg(unix)]\\r\\n            f if f.is_char_device()      => self.colours.char_device(),\\r\\n            #[cfg(unix)]\\r\\n            f if f.is_socket()           => self.colours.socket(),\\r\\n            f if ! f.is_file()           => self.colours.special(),\\r\\n            _                            => self.colours.colour_file(self.file),\\r\\n        };\\r\\n    }\\r\\n\\r\\n    /// For grid's use, to cover the case of hyperlink escape sequences\\r\\n    #[must_use]\\r\\n    pub fn bare_utf8_width(&self) -> usize {\\r\\n        UnicodeWidthStr::width(self.file.name.as_str())\\r\\n    }\\r\\n}\\r\\n\\r\\n/// The set of colours that are needed to paint a file name.\\r\\npub trait Colours: FiletypeColours {\\r\\n    /// The style to paint the path of a symlink’s target, up to but not\\r\\n    /// including the file’s name.\\r\\n    fn symlink_path(&self) -> Style;\\r\\n\\r\\n    /// The style to paint the arrow between a link and its target.\\r\\n    fn normal_arrow(&self) -> Style;\\r\\n\\r\\n    /// The style to paint the filenames of broken links in views that don’t\\r\\n    /// show link targets, and the style to paint the *arrow* between the link\\r\\n    /// and its target in views that *do* show link targets.\\r\\n    fn broken_symlink(&self) -> Style;\\r\\n\\r\\n    /// The style to paint the entire filename of a broken link.\\r\\n    fn broken_filename(&self) -> Style;\\r\\n\\r\\n    /// The style to paint a non-displayable control character in a filename.\\r\\n    fn control_char(&self) -> Style;\\r\\n\\r\\n    /// The style to paint a non-displayable control character in a filename,\\r\\n    /// when the filename is being displayed as a broken link target.\\r\\n    fn broken_control_char(&self) -> Style;\\r\\n\\r\\n    /// The style to paint a file that has its executable bit set.\\r\\n    fn executable_file(&self) -> Style;\\r\\n\\r\\n    /// The style to paint a directory that has a filesystem mounted on it.\\r\\n    fn mount_point(&self) -> Style;\\r\\n\\r\\n    fn colour_file(&self, file: &File<'_>) -> Style;\\r\\n\\r\\n    fn style_override(&self, file: &File<'_>) -> Option<FileNameStyle>;\\r\\n}\\r\\n\\r\\n\"}","command":"shell_command","command_index":6,"command_line":"{\"command\":\"Get-Content -Raw rust-reference\\\\src\\\\output\\\\file_name.rs\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\blog_data\\\\eza-replication-gpt56-max-20260717\\\\project-rebuild-source-port\\\\r-f265dec58c\\\\eza\\\\balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c30a370549cf4c.tool.command_run:call_oD9kYdEveqvVR21Tel12PndU:6","provider_tool_call_id":"call_oD9kYdEveqvVR21Tel12PndU","status":"completed","step":1,"type":"command_execution"},"type":"item.completed"}
{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\nuse std::io::{self, Write};\\r\\n\\r\\nuse term_grid::{Direction, Filling, Grid, GridOptions};\\r\\n\\r\\nuse crate::fs::filter::FileFilter;\\r\\nuse crate::fs::File;\\r\\nuse crate::output::file_name::Options as FileStyle;\\r\\nuse crate::theme::Theme;\\r\\n\\r\\n#[derive(PartialEq, Eq, Debug, Copy, Clone)]\\r\\npub struct Options {\\r\\n    pub across: bool,\\r\\n}\\r\\n\\r\\nimpl Options {\\r\\n    #[must_use]\\r\\n    pub fn direction(self) -> Direction {\\r\\n        if self.across {\\r\\n            Direction::LeftToRight\\r\\n        } else {\\r\\n            Direction::TopToBottom\\r\\n        }\\r\\n    }\\r\\n}\\r\\n\\r\\npub struct Render<'a> {\\r\\n    pub files: Vec<File<'a>>,\\r\\n    pub theme: &'a Theme,\\r\\n    pub file_style: &'a FileStyle,\\r\\n    pub opts: &'a Options,\\r\\n    pub console_width: usize,\\r\\n    pub filter: &'a FileFilter,\\r\\n}\\r\\n\\r\\nimpl Render<'_> {\\r\\n    pub fn render<W: Write>(mut self, w: &mut W) -> io::Result<()> {\\r\\n        self.filter.sort_files(&mut self.files);\\r\\n\\r\\n        let cells = self\\r\\n            .files\\r\\n            .iter()\\r\\n            .map(|file| {\\r\\n                self.file_style\\r\\n                    .for_file(file, self.theme)\\r\\n                    .paint()\\r\\n                    .strings()\\r\\n                    .to_string()\\r\\n            })\\r\\n            .collect();\\r\\n\\r\\n        let grid = Grid::new(\\r\\n            cells,\\r\\n            GridOptions {\\r\\n                filling: Filling::Spaces(2),\\r\\n                direction: self.opts.direction(),\\r\\n                width: self.console_width,\\r\\n            },\\r\\n        );\\r\\n\\r\\n        write!(w, \\\"{grid}\\\")\\r\\n    }\\r\\n}\\r\\n\\r\\n\"}","command":"shell_command","command_index":7,"command_line":"{\"command\":\"Get-Content -Raw rust-reference\\\\src\\\\output\\\\grid.rs\",\"workdir\":\"C:\\\\Users\\\\liuliu\\\\Documents\\\\tura-benchmark\\\\blog_data\\\\eza-replication-gpt56-max-20260717\\\\project-rebuild-source-port\\\\r-f265dec58c\\\\eza\\\\balanced-1\\\\workspace\"}","command_type":"shell_command","id":"runtime-18c30a370549cf4c.tool.command_run:call_oD9kYdEveqvVR21Tel12PndU:7","provider_tool_call_id":"call_oD9kYdEveqvVR21Tel12PndU","status":"completed","step":1,"type":"command_execution"},"type":"item.completed"}
{"item":{"aggregated_output":"{\"exit_code\":0,\"stderr\":\"\",\"stdout\":\"// SPDX-FileCopyrightText: 2024 Christina Sørensen\\r\\n// SPDX-License-Identifier: EUPL-1.2\\r\\n//\\r\\n// SPDX-FileCopyrightText: 2023-2024 Christina Sørensen, eza contributors\\r\\n// SPDX-FileCopyrightText: 2014 Benjamin Sago\\r\\n// SPDX-License-Identifier: MIT\\r\\n//! The `TextCell` type for the details and lines views.\\r\\n\\r\\nuse std::iter::Sum;\\r\\nuse std::ops::{Add, Deref, DerefMut};\\r\\n\\r\\nuse nu_ansi_term::{AnsiString as ANSIString, AnsiStrings as ANSIStrings, Style};\\r\\nuse unicode_width::UnicodeWidthStr;\\r\\n\\r\\n/// An individual cell that holds text in a table, used in the details and\\r\\n/// lines views to store ANSI-terminal-formatted data before it is printed.\\r\\n///\\r\\n/// A text cell is made up of zero or more strings coupled with the\\r\\n/// pre-computed length of all the strings combined. When constructing details\\r\\n/// or grid-details tables, the length will have to be queried multiple times,\\r\\n/// so it makes sense to cache it.\\r\\n///\\r\\n/// (This used to be called `Cell`, but was renamed because there’s a Rust\\r\\n/// type by that name too.)\\r\\n#[derive(PartialEq, Debug, Clone, Default)]\\r\\npub struct TextCell {\\r\\n    /// The contents of this cell, as a vector of ANSI-styled strings.\\r\\n    pub contents: TextCellContents,\\r\\n\\r\\n    /// The Unicode “display width” of this cell.\\r\\n    pub width: DisplayWidth,\\r\\n}\\r\\n\\r\\nimpl Deref for TextCell {\\r\\n    type Target = TextCellContents;\\r\\n\\r\\n    fn deref(&self) -> &Self::Target {\\r\\n        &self.contents\\r\\n    }\\r\\n}\\r\\n\\r\\nimpl TextCell {\\r\\n    /// Creates a new text cell that holds the given text in the given style,\\r\\n    /// computing the Unicode width of the text.\\r\\n    pub fn paint(style: Style, text: String) -> Self {\\r\\n        let width = DisplayWidth::from(&*text);\\r\\n\\r\\n        Self {\\r\\n            contents: vec![style.paint(text)].into(),\\r\\n            width,\\r\\n        }\\r\\n    }\\r\\n\\r\\n    /// Creates a new text cell that holds the given text in the given style,\\r\\n    /// computing the Unicode width of the text. (This could be merged with\\r\\n    /// `paint`, but.)\\r\\n    pub fn paint_str(style: Style, text: &'static str) -> Self {\\r\\n        let width = DisplayWidth::from(text);\\r\\n\\r\\n        Self {\\r\\n            contents: vec![style.paint(text)].into(),\\r\\n            width,\\r\\n        }\\r\\n    }\\r\\n\\r\\n    /// Creates a new “blank” text cell that contains a single hyphen in the\\r\\n    /// given style, which should be the “punctuation” style from a `Colours`\\r\\n    /// value.\\r\\n    ///\\r\\n    /// This is used in place of empty table cells, as it is easier to read\\r\\n    /// tabular data when there is *something* in each cell.\\r\\n    pub fn blank(style: Style) -> Self {\\r\\n        Self {\\r\\n            contents: vec![style.paint(\\\"-\\\")].into(),\\r\\n            width: DisplayWidth::from(1),\\r\\n        }\\r\\n    }\\r\\n\\r\\n    /// Adds the given number of unstyled spaces after this cell.\\r\\n    ///\\r\\n    /// This method allocates a `String` to hold the spaces.\\r\\n    pub fn add_spaces(&mut self, count: usize) {\\r\\n        (*self.width) += count;\\r\\n\\r\\n        let spaces: String = \\\" \\\".repeat(count);\\r\\n        self.contents.0.push(Style::default().paint(spaces));\\r\\n    }\\r\\n\\r\\n    /// Adds the contents of another `ANSIString` to the end of this cell.\\r\\n    pub fn push(&mut self, string: ANSIString<'static>, extra_width: usize) {\\r\\n        self.contents.0.push(string);\\r\\n        (*self.width) += extra_width;\\r\\n    }\\r\\n\\r\\n    /// Adds all the contents of another `TextCell` to the end of this cell.\\r\\n    pub fn append(&mut self, other: Self) {\\r\\n        (*self.width) += *other.width;\\r\\n        self.contents.0.extend(other.contents.0);\\r\\n    }\\r\\n}\\r\\n\\r\\n// I’d like to eventually abstract cells so that instead of *every* cell\\r\\n// storing a vector, only variable-length cells would, and individual cells\\r\\n// would just store an array of a fixed length (which would usually be just 1\\r\\n// or 2), which wouldn’t require a heap allocation.\\r\\n//\\r\\n// For examples, look at the `render_*` methods in the `Table` object in the\\r\\n// details view:\\r\\n//\\r\\n// - `render_blocks`, `inode`, and `links` will always return a\\r\\n//   one-string-long TextCell;\\r\\n// - `render_size` will return one or two strings in a TextCell, depending on\\r\\n//   the size and whether one is present;\\r\\n// - `render_permissions` will return ten or eleven strings;\\r\\n// - `filename` and `symlink_filename` in the output module root return six or\\r\\n//   five strings.\\r\\n//\\r\\n// In none of these cases are we dealing with a *truly variable* number of\\r\\n// strings: it is only when the strings are concatenated together do we need a\\r\\n// growable, heap-allocated buffer.\\r\\n//\\r\\n// So it would be nice to abstract the `TextCell` type so instead of a `Vec`,\\r\\n// it can use anything of type `T: IntoIterator<Item=ANSIString<’static>>`.\\r\\n// This would allow us to still hold all the data, but allocate less.\\r\\n//\\r\\n// But exa still has bugs and I need to fix those first :(\\r\\n\\r\\n/// The contents of a text cell, as a vector of ANSI-styled strings.\\r\\n///\\r\\n/// It’s possible to use this type directly in the case where you want a\\r\\n/// `TextCell` but aren’t concerned with tracking its width, because it occurs\\r\\n/// in the final cell of a table or grid and there’s no point padding it. This\\r\\n/// happens when dealing with file names.\\r\\n#[derive(PartialEq, Debug, Clone, Default)]\\r\\npub struct TextCellContents(Vec<ANSIString<'static>>);\\r\\n\\r\\nimpl From<Vec<ANSIString<'static>>> for TextCellContents {\\r\\n    fn from(strings: Vec<ANSIString<'static>>) -> Self {\\r\\n        Self(strings)\\r\\n    }\\r\\n}\\r\\n\\r\\nimpl Deref for TextCellContents {\\r\\n    type Target = [ANSIString<'static>];\\r\\n\\r\\n    fn deref(&self) -> &Self::Target {\\r\\n        &self.0\\r\\n    }\\r\\n}\\r\\n\\r\\n// No DerefMut implementation here — it would be publicly accessible, and as\\r\\n// the contents only get changed in this module, the mutators in the struct\\r\\n// above can just access the value directly.\\r\\n\\r\\nimpl TextCellContents {\\r\\n    /// Produces an `ANSIStrings` value that can be used to print the styled\\r\\n    /// values of this cell as an ANSI-terminal-formatted string.\\r\\n    pub fn strings(&self) -> ANSIStrings<'_> {\\r\\n        ANSIStrings(&self.0)\\r\\n    }\\r\\n\\r\\n    /// Calculates the width that a cell with these contents would take up, by\\r\\n    /// counting the number of characters in each unformatted ANSI string.\\r\\n    pub fn width(&self) -> DisplayWidth {\\r\\n        self.0\\r\\n            .iter()\\r\\n            .map(|anstr| DisplayWidth::from(anstr.as_str()))\\r\\n            .sum()\\r\\n    }\\r\\n\\r\\n    /// Promotes these contents to a full cell containing them alongside\\r\\n    /// their calculated width.\\r\\n    pub fn promote(self) -> TextCell {\\r\\n        TextCell {\\r\\n            width: self.width(),\\r\\n            contents: self,\\r\\n        }\\r\\n    }\\r\\n}\\r\\n\\r\\n/// The Unicode “display width” of a string.\\r\\n///\\r\\n/// This is related to the number of *graphemes* of a string, rather than the\\r\\n/// number of *characters*, or *bytes*: although most characters are one\\r\\n/// column wide, a few can be two columns wide, and this is important to note\\r\\n/// when calculating widths for displaying tables in a terminal.\\r\\n///\\r\\n/// This type is used to ensure that the width, rather than the length, is\\r\\n/// used when constructing a `TextCell` — it’s too easy to write something\\r\\n/// like `file_name.len()` and assume it will work!\\r\\n///\\r\\n/// It has `From