dout=subprocess.PIPE,\n+        stderr=subprocess.PIPE,\n+        check=False,\n+    )\n+    return Result(completed.returncode, completed.stdout, completed.stderr)\n+\n+\n+def make_fixture(base: Path) -> Path:\n+    fixture = base / \"fixture\"\n+    fixture.mkdir()\n+    (fixture / \"alpha.txt\").write_bytes(b\"a\")\n+    (fixture / \"Beta.TXT\").write_bytes(b\"beta\")\n+    (fixture / \"item2.log\").write_bytes(b\"22\")\n+    (fixture / \"item10.log\").write_bytes(b\"ten bytes!\")\n+    (fixture / \".dotfile\").write_bytes(b\"dot\")\n+    (fixture / \"_legacy\").write_bytes(b\"legacy\")\n+    (fixture / \"space name\").write_bytes(b\"space\")\n+    sub = fixture / \"subdir\"\n+    sub.mkdir()\n+    (sub / \"child.txt\").write_bytes(b\"child\")\n+    deep = sub / \"nested\"\n+    deep.mkdir()\n+    (deep / \"leaf\").write_bytes(b\"leaf\")\n+\n+    # Whole-second timestamps avoid filesystem precision differences between\n+    # processes while still exercising all date-based sort directions.\n+    epoch = 1_700_000_000\n+    for index, path in enumerate(sorted(fixture.rglob(\"*\"), key=str)):\n+        stamp = epoch + index * 60\n+        os.utime(path, (stamp, stamp), follow_symlinks=False)\n+    return fixture\n+\n+\n+def cases(path: Path, missing: Path) -> list[Case]:\n+    common = (\"--color=never\", \"--icons=never\")\n+    target = str(path)\n+    return [\n+        Case(\"version\", (\"--version\",)),\n+        Case(\"unknown-option\", (\"--not-an-eza-option\",)),\n+        Case(\"missing-path\", (*common, str(missing))),\n+        Case(\"lines\", (*common, \"--oneline\", target)),\n+        Case(\"all\", (*common, \"--oneline\", \"--all\", target)),\n+        Case(\"almost-all\", (*common, \"--oneline\", \"--almost-all\", target)),\n+        Case(\"reverse\", (*common, \"--oneline\", \"--reverse\", target)),\n+        Case(\"sort-name-sensitive\", (*common, \"--oneline\", \"--sort=Name\", target)),\n+        Case(\"sort-extension\", (*common, \"--oneline\", \"--sort=extension\", target)),\n+        Case(\"sort-size\", (*common, \"--oneline\", \"--sort=size\", target)),\n+        Case(\"sort-modified\", (*common, \"--oneline\", \"--sort=modified\", target)),\n+        Case(\"dirs-first\", (*common, \"--oneline\", \"--group-directories-first\", target)),\n+        Case(\"only-dirs\", (*common, \"--oneline\", \"--only-dirs\", target)),\n+        Case(\"only-files\", (*common, \"--oneline\", \"--only-files\", target)),\n+        Case(\"ignore-glob\", (*common, \"--oneline\", \"--ignore-glob=*.log\", target)),\n+        Case(\"classify\", (*common, \"--oneline\", \"--classify=always\", target)),\n+        Case(\"quotes\", (*common, \"--oneline\", target)),\n+        Case(\"no-quotes\", (*common, \"--oneline\", \"--no-quotes\", target)),\n+        Case(\"grid-narrow\", (*common, \"--grid\", \"--width=18\", target)),\n+        Case(\"grid-across\", (*common, \"--grid\", \"--across\", \"--width=32\", target)),\n+        Case(\"long\", (*common, \"--long\", target)),\n+        Case(\"long-bytes\", (*common, \"--long\", \"--bytes\", target)),\n+        Case(\"long-header\", (*common, \"--long\", \"--header\", target)),\n+        Case(\"long-no-fields\", (*common, \"--long\", \"--no-permissions\", \"--no-filesize\", \"--no-time\", target)),\n+        Case(\"long-created\", (*common, \"--long\", \"--created\", \"--time-style=long-iso\", target)),\n+        Case(\"tree\", (*common, \"--tree\", target)),\n+        Case(\"tree-level-one\", (*common, \"--tree\", \"--level=1\", target)),\n+        Case(\"tree-long\", (*common, \"--tree\", \"--long\", \"--no-time\", target)),\n+        Case(\"recurse\", (*common, \"--oneline\", \"--recurse\", \"--level=2\", target)),\n+        Case(\"stdin-path\", (*common, \"--oneline\", \"--stdin\"), (target + \"\\n\").encode()),\n+    ]\n+\n+\n+def escaped(data: bytes) -> str:\n+    return repr(data.decode(\"utf-8\", errors=\"backslashreplace\"))\n+\n+\n+def main() -> int:\n+    parser = argparse.ArgumentParser()\n+    parser.add_argument(\n+        \"--candidate\",\n+        nargs=\"+\",\n+        default=[sys.executable, str(ROOT / \"eza_port.py\")],\n+        help=\"candidate command, before eza arguments\",\n+    )\n+    parser.add_argument(\"--case\", action=\"append\", dest=\"selected\")\n+    args = parser.parse_args()\n+\n+    if not REFERENCE.is_file():\n+        print(f\"reference binary not found: {REFERENCE}\", file=sys.stderr)\n+        return 2\n+\n+    failures = 0\n+    with tempfile.TemporaryDirectory(prefix=\"eza-port-\", dir=ROOT / \".tura\") as tmp:\n+        temp = Path(tmp)\n+        fixture = make_fixture(temp)\n+        corpus = cases(fixture, temp / \"missing\")\n+        if args.selected:\n+            names = set(args.selected)\n+            corpus = [case for case in corpus if case.name in names]\n+\n+        for case in corpus:\n+            expected = run([str(REFERENCE)], case, ROOT)\n+            actual = run(args.candidate, case, ROOT)\n+            if actual == expected:\n+                print(f\"PASS {case.name}\")\n+                continue\n+            failures += 1\n+            print(f\"FAIL {case.name}\")\n+            if actual.status != expected.status:\n+                print(f\"  status expected={expected.status} actual={actual.status}\")\n+            if actual.stdout != expected.stdout:\n+                print(f\"  stdout expected={escaped(expected.stdout)}\")\n+                print(f\"  stdout actual  ={escaped(actual.stdout)}\")\n+            if actual.stderr != expected.stderr:\n+                print(f\"  stderr expected={escaped(expected.stderr)}\")\n+                print(f\"  stderr actual  ={escaped(actual.stderr)}\")\n+\n+    print(f\"{len(corpus) - failures}/{len(corpus)} differential cases passed\")\n+    return 1 if failures else 0\n+\n+\n+if __name__ == \"__main__\":\n+    raise SystemExit(main())\n*** End Patch","command_type":"apply_patch","id":"runtime-18c30a59f72e4aa0.tool.command_run:call_MT7v