  flags: list[Occurrence]","    paths: list[str]","","    def occurrences(self, name: str) -> list[Occurrence]:","        return [flag for flag in self.flags if flag.spec.long == name]","","    def has(self, name: str) -> bool:","        return any(flag.spec.long == name for flag in self.flags)","","    def count(self, name: str) -> int:","        return sum(flag.spec.long == name for flag in self.flags)","","    def get(self, name: str) -> str | None:","        for flag in reversed(self.flags):","            if flag.spec.long == name:","                return flag.value","        return None","","    def last_of(self, names: Iterable[str]) -> Occurrence | None:","        wanted = set(names)","        return next(","            (flag for flag in reversed(self.flags) if flag.spec.long in wanted),","            None,","        )","","","@dataclass","class Options:","    paths: list[str]","    special: str | None","    view: str","    width: int | None","    across: bool","    recurse: bool","    tree: bool","    max_depth: int | None","    treat_dirs_as_files: bool","    sort: str","    reverse: bool","    dirs_first: bool","    dirs_last: bool","    dot_mode: int","    only_dirs: bool","    only_files: bool","    no_symlinks: bool","    show_symlinks: bool","    ignore_globs: tuple[str, ...]","    classify: str","    quote: bool","    absolute: str","    dereference: bool","    follow_symlinks: bool","    header: bool","    size_format: str","    permissions: bool","    filesize: bool","    file_flags: bool","    time_types: tuple[str, ...]","    time_style: str","    stdin_mode: bool","    stdin_separator: str","    hyperlink: bool","    total_size: bool","","    @property","    def long_view(self) -> bool:","        return self.view in (\"details\", \"grid-details\") and not (","            self.tree and self.view == \"details\" and not self.time_types","        )","","","def _flag_label(spelling: str) -> str:","    return spelling","","","def _needs_value(spec: FlagSpec, spelling: str) -> OptionError:","    choices = \"\"","    if spec.choices:","        choices = f\" (choices: {', '.join(spec.choices)})\"","    return OptionError(f\"Flag {_flag_label(spelling)} needs a value{choices}\")","","","def parse_args(argv: Sequence[str]) -> Matches:","    flags: list[Occurrence] = []","    paths: list[str] = []","    parsing = True","    index = 0","","    while index < len(argv):","        token = argv[index]","        index += 1","        if not parsing:","            paths.append(token)","            continue","        if token == \"--\":","            parsing = False","            continue","        if token.startswith(\"--\"):","            raw = token[2:]","            if \"=\" in raw:","                name, supplied = raw.split(\"=\", 1)","                spec = LONG_FLAGS.get(name)","                if spec is None:","                    raise OptionError(f\"Unknown argument --{name}\")","                spelling = f\"--{name}\"","                if spec.value == \"forbidden\":","                    raise OptionError(f\"Flag {spelling} cannot take a value\")","                flags.append(Occurrence(spec, spelling, supplied))","                continue","","            spec = LONG_FLAGS.get(raw)","            if spec is None:","                raise OptionError(f\"Unknown argument --{raw}\")","            spelling = f\"--{raw}\"","            if spec.value == \"forbidden\":","                flags.append(Occurrence(spec, spelling, None))","            elif spec.value == \"necessary\":","                if index >= len(argv):","                    raise _needs_value(spec, spelling)","                flags.append(Occurrence(spec, spelling, argv[index]))","                index += 1","            elif index < len(argv) and spec.choices and argv[index] in spec.choices:","                flags.append(Occurrence(spec, spelling, argv[index]))","                index += 1","            else:","                flags.append(Occurrence(spec, spelling, spec.default))","            continue","","        if token.startswith(\"-\") and token != \"-\":","            raw = token[1:]","            if \"=\" in raw:","                before, supplied = raw.split(\"=\", 1)","                if not before:","                    paths.append(token)","                    continue","                for char in before[:-1]:","                    spec = SHORT_FLAGS.get(char)","                    if spec is None:","                        raise OptionError(f\"Unknown argument -{char}\")","                    spelling = f\"-{char}\"","                    if spec.value == \"necessary\":","                        raise _needs_value(spec, spelling)","                    value = spec.default if spec.value == \"optional\" else None","                    flags.append(Occurrence(spec, spelling, value))","                char = before[-1]","                spec = SHORT_FLAGS.get(char)","                if spec is None:","                    raise OptionError(f\"Unknown argument -{char}\")","                spelling = f\"-{char}\"","                if spec.value == \"forbidden\":","                    raise OptionError(f\"Flag {spelling} cannot take a value\")","                flags.append(Occurrence(spec, spelling, supplied))","                continue","","            char_index = 0","            while char_index < len(raw):","                char = raw[char_index]","                spec = SHORT_FLAGS.get(char)","                if spec is None:","                    raise OptionError(f\"Unknown argument -{char}\")","                spelling = f\"-{char}\"","                if spec.value == \"forbidden\":","                    flags.append(Occurrence(spec, spelling, None))","                    char_index += 1","                    continue","                remnants = raw[char_index + 1 :]","                if spec.value == \"necessary\":","                    if remnants:","                        flags.append(Occurrence(spec, spelling, remnants))","                    elif index < len(argv):","                        flags.append(Occurrence(spec, spelling, argv[index]))","                        index += 1","                    else:","                        raise _needs_value(spec, spelling)","                    break","                if remnants:","                    if spec.choices and remnants in spec.choices:","                        flags.append(Occurrence(spec, spelling, remnants))","                    else:","                        raise OptionError(f\"Flag {spelling} cannot take a value\")","                    break","                if index < len(argv) and spec.choices and argv[index] in spec.choices:","                    flags.append(Occurrence(spec, spelling, argv[index]))","                    index += 1","                else:","                    flags.append(Occurrence(spec, spelling, spec.default))","                break","            continue","","        paths.append(token)","","    return Matches(flags, paths)","","","def _debug(value: str) -> str:","    return json.dumps(value, ensure_ascii=False)","","","def _bad(spec_name: str, value: str, choices: bool = False) -> OptionError:","    spec = LONG_FLAGS[spec_name]","    suffix = \"\"","    if choices and spec.choices:","        suffix = f\" (choices: {', '.join(spec.choices)})\"","    return OptionError(","        f\"Option {spec.display} has no {_debug(value)} setting{suffix}\"","    )","","","def _parse_usize(value: str, spec_name: str) -> int:","    if not value:","        reason = \"cannot parse integer from empty string\"","    elif not value.isascii() or not value.isdigit():","        reason = \"invalid digit found in string\"","    else:","        number = int(value)","        if number <= (1 << 64) - 1:","            return number","        reason = \"number too large to fit in target type\"","    spec = LONG_FLAGS[spec_name]","    raise OptionError(","        f\"Value {_debug(value)}