has(\"treat-dirs-as-files\") or matches.has(\"list-dirs\")","    treat_dirs = tree or (not recurse and as_file)","    max_depth = None","    if recurse and matches.get(\"level\") is not None:","        max_depth = _parse_usize(matches.get(\"level\") or \"\", \"level\")","","    all_count = matches.count(\"all\")","    if tree and all_count >= 2:","        raise OptionError(\"Option --tree is useless given --all --all\")","    if all_count >= 2:","        dot_mode = 2","    elif all_count or matches.has(\"almost-all\"):","        dot_mode = 1","    else:","        dot_mode = 0","","    sort_word = matches.get(\"sort\") or \"name\"","    sort_aliases = {","        \"filename\": \"name\", \"Filename\": \"Name\",","        \".filename\": \".name\", \".Filename\": \".Name\",","        \"filesize\": \"size\", \"ext\": \"extension\", \"Ext\": \"Extension\",","        \"date\": \"modified\", \"time\": \"modified\", \"mod\": \"modified\",","        \"new\": \"modified\", \"newest\": \"modified\",","        \"age\": \"age\", \"old\": \"age\", \"oldest\": \"age\",","        \"ch\": \"changed\", \"acc\": \"accessed\", \"cr\": \"created\",","    }","    sort_word = sort_aliases.get(sort_word, sort_word)","    valid_sorts = {","        \"name\", \"Name\", \".name\", \".Name\", \"size\", \"extension\",","        \"Extension\", \"modified\", \"age\", \"changed\", \"accessed\",","        \"created\", \"inode\", \"type\", \"none\",","    }","    if sort_word not in valid_sorts or (os.name == \"nt\" and sort_word == \"inode\"):","        raise _bad(\"sort\", matches.get(\"sort\") or sort_word, choices=True)","","    classify = matches.get(\"classify\") or \"never\"","    if classify == \"automatic\":","        classify = \"auto\"","    if classify not in WHEN:","        raise _bad(\"classify\", classify)","","    absolute = matches.get(\"absolute\") or \"off\"","    absolute = {\"yes\": \"on\", \"no\": \"off\"}.get(absolute, absolute)","    if absolute not in (\"on\", \"follow\", \"off\"):","        raise _bad(\"absolute\", absolute)","","    color_occurrence = matches.last_of((\"color\", \"colour\"))","    if color_occurrence is not None:","        color = color_occurrence.value or \"auto\"","        if color == \"automatic\":","            color = \"auto\"","        if color not in WHEN:","            raise _bad(\"color\", color)","","    icons = matches.get(\"icons\")","    if icons is not None:","        if icons == \"automatic\":","            icons = \"auto\"","        if icons not in WHEN:","            raise _bad(\"icons\", icons)","","    scale_mode = matches.last_of((\"color-scale-mode\", \"colour-scale-mode\"))","    if scale_mode is not None and scale_mode.value not in (\"fixed\", \"gradient\"):","        raise _bad(\"color-scale-mode\", scale_mode.value or \"\")","    scale = matches.last_of((\"color-scale\", \"colour-scale\"))","    if scale is not None:","        for word in (scale.value or \"\").split(\",\"):","            if word not in (\"all\", \"age\", \"size\"):","                raise _bad(\"color-scale\", word)","","    ignore_word = matches.get(\"ignore-glob\")","    ignore_globs = tuple(ignore_word.split(\"|\")) if ignore_word is not None else ()","","    long_table = view in (\"details\", \"grid-details\") and not (","        tree and not matches.has(\"long\")","    )","    size_format = \"decimal\"","    size_occurrence = matches.last_of((\"binary\", \"bytes\"))","    if long_table and size_occurrence is not None:","        size_format = \"binary\" if size_occurrence.spec.long == \"binary\" else \"bytes\"","","    time_types: tuple[str, ...] = ()","    time_style = \"default\"","    if long_table:","        if matches.has(\"no-time\"):","            time_types = ()","        elif matches.get(\"time\") is not None:","            word = matches.get(\"time\") or \"\"","            aliases = {\"mod\": \"modified\", \"ch\": \"changed\", \"acc\": \"accessed\", \"cr\": \"created\"}","            word = aliases.get(word, word)