tches.has(\"no-filesize\"),","        file_flags=long_table and matches.has(\"flags\"),","        time_types=time_types,","        time_style=time_style,","        stdin_mode=stdin_mode,","        stdin_separator=environment.get(\"EZA_STDIN_SEPARATOR\", \"\\n\"),","        hyperlink=matches.has(\"hyperlink\"),","        total_size=matches.has(\"total-size\"),","    )","","","def _special(paths: list[str], special: str) -> Options:","    return Options(","        paths=paths, special=special, view=\"lines\", width=None, across=False,","        recurse=False, tree=False, max_depth=None, treat_dirs_as_files=False,","        sort=\"name\", reverse=False, dirs_first=False, dirs_last=False,","        dot_mode=0, only_dirs=False, only_files=False, no_symlinks=False,","        show_symlinks=False, ignore_globs=(), classify=\"never\", quote=True,","        absolute=\"off\", dereference=False, follow_symlinks=False, header=False,","        size_format=\"decimal\", permissions=False, filesize=False,","        file_flags=False, time_types=(), time_style=\"default\", stdin_mode=False,","        stdin_separator=\"\\n\", hyperlink=False, total_size=False,","    )"],"path":"eza_py/options.py"}],"command":"apply_patch","command_index":1,"command_line":"*** Begin Patch\n*** Add File: eza_py/options.py\n+\"\"\"Command-line parsing and option deduction compatible with eza v0.23.3.\"\"\"\n+\n+from __future__ import annotations\n+\n+from dataclasses import dataclass\n+import json\n+import os\n+import shutil\n+from typing import Iterable, Mapping, Sequence\n+\n+\n+WHEN = (\"always\", \"auto\", \"never\")\n+SORT_CHOICES = (\n+    \"name\",\n+    \"Name\",\n+    \"size\",\n+    \"extension\",\n+    \"Extension\",\n+    \"modified\",\n+    \"changed\",\n+    \"accessed\",\n+    \"created\",\n+    \"inode\",\n+    \"type\",\n+    \"none\",\n+)\n+TIME_CHOICES = (\"modified\", \"changed\", \"accessed\", \"created\")\n+TIME_STYLE_CHOICES = (\"default\", \"long-iso\", \"full-iso\", \"iso\", \"relative\")\n+\n+\n+@dataclass(frozen=True)\n+class FlagSpec:\n+    long: str\n+    short: str | None = None\n+    value: str = \"forbidden\"\n+    choices: tuple[str, ...] | None = None\n+    default: str | None = None\n+\n+    @property\n+    def display(self) -> str:\n+        suffix = f\" (-{self.short})\" if self.short else \"\"\n+        return f\"--{self.long}{suffix}\"\n+\n+\n+def _specs() -> tuple[FlagSpec, ...]:\n+    f = FlagSpec\n+    return (\n+        f(\"version\", \"v\"), f(\"help\", \"?\"),\n+        f(\"oneline\", \"1\"), f(\"long\", \"l\"), f(\"grid\", \"G\"),\n+        f(\"across\", \"x\"), f(\"recurse\", \"R\"), f(\"tree\", \"T\"),\n+        f(\"classify\", \"F\", \"optional\", WHEN, \"auto\"),\n+        f(\"dereference\", \"X\"), f(\"width\", \"w\", \"necessary\"),\n+        f(\"no-quotes\"),\n+        f(\"absolute\", None, \"optional\", (\"on\", \"follow\", \"off\"), \"on\"),\n+        f(\"follow-symlinks\"),\n+        f(\"color\", None, \"optional\", WHEN, \"auto\"),\n+        f(\"colour\", None, \"optional\", WHEN, \"auto\"),\n+        f(\"color-scale\", None, \"optional\", (\"all\", \"size\", \"age\"), \"all\"),\n+        f(\"colour-scale\", None, \"optional\", (\"all\", \"size\", \"age\"), \"all\"),\n+        f(\"color-scale-mode\", None, \"necessary\", (\"fixed\", \"gradient\")),\n+        f(\"colour-scale-mode\", None, \"necessary\", (\"fixed\", \"gradient\")),\n+        f(\"all\", \"a\"), f(\"almost-all\", \"A\"),\n+        f(\"treat-dirs-as-files\", \"d\"), f(\"list-dirs\"),\n+        f(\"level\", \"L\", \"necessary\"), f(\"reverse\", \"r\"),\n+        f(\"sort\", \"s\", \"necessary\", SORT_CHOICES),\n+        f(\"ignore-glob\", \"I\", \"necessary\"), f(\"git-ignore\"),\n+        f(\"group-directories-first\"), f(\"group-directories-last\"),\n+        f(\"only-dirs\", \"D\"), f(\"only-files\", \"f\"),\n+        f(\"no-symlinks\"), f(\"show-symlinks\"),\n+        f(\"binary\", \"b\"), f(\"bytes\", \"B\"), f(\"group\", \"g\"),\n+        f(\