     current = Entry.direct(str(path), options.dereference)\",\"        current.name = \\\".\\\"\",\"        current.parented = True\",\"        current.is_all_all = True\",\"        parent = Entry.direct(str(path / \\\"..\\\"), options.dereference)\",\"        parent.name = \\\"..\\\"\",\"        parent.parented = True\",\"        parent.is_all_all = True\",\"        entries.extend((current, parent))\",\"\",\"    with os.scandir(path) as iterator:\",\"        names = [item.name for item in iterator]\",\"    for name in names:\",\"        entry = Entry.child(path, name, options.dereference)\",\"        if options.dot_mode == 0 and (\",\"            name.startswith(\\\".\\\")\",\"            or name.startswith(\\\"_\\\")\",\"            or bool(entry.attributes & FILE_ATTRIBUTE_HIDDEN)\",\"        ):\",\"            continue\",\"        entries.append(entry)\",\"    return filter_children(entries, options, options.recurse)\",\"\",\"\",\"def _ignored(name: str, patterns: Iterable[str]) -> bool:\",\"    return any(fnmatch.fnmatchcase(name, pattern) for pattern in patterns)\",\"\",\"\",\"def filter_argument_entries(entries: list[Entry], options: Options) -> list[Entry]:\",\"    return [entry for entry in entries if not _ignored(entry.name, options.ignore_globs)]\",\"\",\"\",\"def filter_children(entries: list[Entry], options: Options, is_recurse: bool) -> list[Entry]:\",\"    result = [entry for entry in entries if not _ignored(entry.name, options.ignore_globs)]\",\"    filtered: list[Entry] = []\",\"    for entry in result:\",\"        only_dirs = options.only_dirs\",\"        only_files = options.only_files\",\"        no_links = options.no_symlinks\",\"        show_links = options.show_symlinks\",\"        keep = True\",\"        if only_dirs and not only_files and not show_links:\",\"            keep = entry.is_dir\",\"        elif only_dirs and not only_files and show_links:\",\"            keep = entry.is_dir or entry.points_to_directory\",\"        elif only_file