red or _natural_compare(left.name, right.name, False)","    if field == \"inode\":","        return _cmp(getattr(left.stat, \"st_ino\", 0), getattr(right.stat, \"st_ino\", 0))","    return 0","","","def sort_entries(entries: list[Entry], options: Options) -> list[Entry]:","    result = sorted(entries, key=cmp_to_key(lambda a, b: _entry_compare(a, b, options.sort)))","    if options.reverse:","        result.reverse()","    if options.dirs_first:","        result.sort(key=lambda entry: not entry.points_to_directory)","    elif options.dirs_last:","        result.sort(key=lambda entry: entry.points_to_directory)","    return result"],"path":"eza_py/filesystem.py"}],"command":"apply_patch","command_index":2,"command_line":"*** Begin Patch\n*** Add File: eza_py/filesystem.py\n+\"\"\"Filesystem model, filtering, and sorting for the Python eza port.\"\"\"\n+\n+from __future__ import annotations\n+\n+from dataclasses import dataclass\n+from functools import cmp_to_key\n+import fnmatch\n+import os\n+from pathlib import Path\n+import re\n+import stat as stat_module\n+from typing import Iterable\n+\n+from .options import Options\n+\n+\n+FILE_ATTRIBUTE_READONLY = 0x1\n+FILE_ATTRIBUTE_HIDDEN = 0x2\n+FILE_ATTRIBUTE_SYSTEM = 0x4\n+FILE_ATTRIBUTE_DIRECTORY = 0x10\n+FILE_ATTRIBUTE_ARCHIVE = 0x20\n+FILE_ATTRIBUTE_REPARSE_POINT = 0x400\n+\n+\n+@dataclass\n+class Entry:\n+    path: Path\n+    raw_path: str\n+    name: str\n+    stat: os.stat_result\n+    parented: bool = False\n+    is_all_all: bool = False\n+    dereference: bool = False\n+\n+    @classmethod\n+    def direct(cls, raw_path: str, dereference: bool = False) -> \"Entry\":\n+        path = Path(raw_path)\n+        metadata = path.lstat()\n+        name = path.name\n+        if not name:\n+            name = path.anchor or raw_path\n+        return cls(path, raw_path, name, metadata, False, False, dereference)\n+\n+    @classmethod\n+    def child(cls, parent: Path, name: str, dereference: bool = False) -> \"Entry\":\n+        path = parent / name\n+        return cls(path, str(path), name, path.lstat(), True, False, dereference)\n+\n+    @property\n+    def attributes(self) -> int:\n+        value = getattr(self.stat, \"st_file_attributes\", None)\n+        if value is not None:\n+            return int(value)\n+        result = 0\n+        if stat_module.S_ISDIR(self.stat.st_mode):\n+            result |= FILE_ATTRIBUTE_DIRECTORY\n+        elif stat_module.S_ISREG(self.stat.st_mode):\n+            result |= FILE_ATTRIBUTE_ARCHIVE\n+        if not self.stat.st_mode & stat_module.S_IWUSR:\n+            result |= FILE_ATTRIBUTE_READONLY\n+        return result\n+\n+    @property\n+    def is_link(self) -> bool:\n+        return stat_module.S_ISLNK(self.stat.st_mode)\n+\n+    @property\n+    def is_dir(self) -> bool:\n+        return stat_module.S_ISDIR(self.stat.st_mode) and not self.is_link\n+\n+    @property\n+    def is_file(self) -> bool:\n+        return stat_module.S_ISREG(self.stat.st_mode) and not self.is_link\n+\n+    @property\n+    def points_to_directory(self) -> bool:\n+        try:\n+            return self.path.is_dir()\n+        except OSError:\n+            return False\n+\n+    @property\n+    def extension(self) -> str | None:\n+        position = self.name.rfind(\".\")\n+        return self.name[position + 1 :].lower() if position >= 0 else None\n+\n+    @property\n+    def length(self) -> int:\n+        return int(self.stat.st_size)\n+\n+    def timestamp(self, kind: str) -> float | None:\n+        if self.dereference and self.is_link:\n+            try:\n+                metadata = self.path.stat()\n+            except OSError:\n+                return None\n+        else:\n+            metadata = self.stat\n+        if kind in (\"modified\", \"changed\"):\n+            return float(metadata.st_mtime)\n+        if kind == \"accessed\":\n+            return float(metadata.st_atime)\n+        if kind == \"created\":\n+            return float(getattr(metadata, \"st_birthtime\", metadata.st_ctime))\n+        return None\n+\n+    @property\n+    def type_order(self) -> int:\n+        if self.is_dir:\n+            return 0\n+        if self.is_file:\n+            return 1\n+        if self.is_link:\n+            return 2\n+        return 7\n+\n+\n+def read_directory(path: Path, options: Options) -> list[Entry]:\n+    entries: list[Entry] = []\n+    if options.dot_mode == 2:\n+        current = Entry.direct(str(path), options.dereference)\n+        current.name = \".\"\n+        current.parented = True\n+        current.is_all_all = True\n+        parent = Entry.direct(str(path / \"..\"), options.dereference)\n+        parent.name = \"..\"\n+        parent.parented = True\n+        parent.is_all_all = True\n+        entries.extend((current, parent))\n+\n+    with os.scandir(path) as iterator:\n+        names = [item.name for item in iterator]\n+    for name in names:\n+        entry = Entry.child(path, name, options.dereference)\n+        if options.dot_mode == 0 and (\n+            name.startswith(\".\")\n+            or name.startswith(\"_\")\n+            or bool(entry.attributes & FILE_ATTRIBUTE_HIDDEN)\n+        ):\n+            continue\n+        entries.append(entry)\n+    return filter_children(entries, options, options.recurse)\n+\n+\n+def _ignored(name: str, patterns: Iterable[str]) -> bool:\n+    return any(fnmatch.fnmatchcase(name, pattern) for pattern in patterns)\n+\n+\n+def filter_argument_entries(entries: list[Entry], options: Options) -> list[Entry]:\n+    return [entry for entry in entries if not _ignored(entry.name, options.ignore_globs)]\n+\n+\n+def filter_children(entries: list[Entry], options: Options, is_recurse: bool) -> list[Entry]:\n+    result = [entry for entry in entries if not _ignored(entry.name, options.ignore_globs)]\n+    filtered: list[Entry] = []\n+    for entry in result:\n+        only_dirs = options.only_dirs\n+        only_files = options.only_files\n+        no_links = options.no_symlinks\n+        show_links = options.show_symlinks\n+        keep = True\n+        if only_dirs and not only_files and not show_links:\n+            keep = entry.is_dir\n+        elif only_dirs and not only_files and show_links:\n+            keep = entry.is_dir or entry.points_to_directory\n+        elif only_files and not only_dirs and not show_links:\n+            keep = True if is_recurse else entry.is_file\n+        elif only_files and not only_dirs and show_links:\n+            keep = True if is_recurse else (\n+                entry.is_file or (entry.is_link and not entry.points_to_directory)\n+            )\n+        elif no_links and not only_dirs and not only_files and not show_links:\n+            keep = not entry.is_link\n+        if keep:\n+            filtered.append(entry)\n+    return sort_entries(filtered, options)\n+\n+\n+_NATURAL_PART = re.compile(r\"(\\d+)\")\n+\n+\n+def _natural_parts(value: str, ignore_case: bool) -> list[tuple[int, object]]:\n+    if ignore_case:\n+        value = value.lower()\n+    pieces: list[tuple[int, object]] = []\n+    for part in _NATURAL_PART.split(value):\n+        if not part:\n+            continue\n+        if part.isdigit():\n+            pieces.append((0, int(part)))\n+        else:\n+            pieces.append((1, part))\n+    return pieces\n+\n+\n+def _cmp(left: object, right: object) -> int:\n+    return (left > right) - (left < right)\n+\n+\n+def _natural_compare(left: str, right: str, ignore_case: bool) -> int:\n+    return _cmp(_natural_parts(left, ignore_case), _natural_parts(right, ignore_case))\n+\n+\n+def _optional_compare(left: object | None, right: object | None) -> int:\n+    if left is None:\n+        return 0 if right is None else -1\n+    if right is None:\n+        return 1\n+    return _cmp(left, right)\n+\n+\n+def _entry_compare(left: Entry, right: Entry, field: str) -> int:\n+    if field == \"none\":\n+        return 0\n+    if field in (\"name\", \"Name\", \".name\", \".Name\"):\n+        left_n