\"    return \\\"\\\".join(f\\\"{render_name(entry, options, link_paths=True)}\\\\n\\\" for entry in entries)\",\"\",\"\",\"def _grid_layout(cells: list[str], width: int, across: bool, spacing: int = 2) -> str:\",\"    if not cells:\",\"        return \\\"\\\"\",\"    cell_widths = [display_width(cell) for cell in cells]\",\"    count = len(cells)\",\"    chosen_columns = 1\",\"    chosen_rows = count\",\"    chosen_widths = [max(cell_widths)]\",\"\",\"    for columns in range(count, 0, -1):\",\"        rows = math.ceil(count / columns)\",\"        widths = [0] * columns\",\"        for index, cell_width in enumerate(cell_widths):\",\"            column = index % columns if across else index // rows\",\"            if column < columns:\",\"                widths[column] = max(widths[column], cell_width)\",\"        used_columns = max((index for index, value in enumerate(widths) if value or index == 0), default=0) + 1\",\"        widths = widths[:used_columns]\",\"        total = sum(widths) + spacing * max(0, len(widths) - 1)\",\"        if total <= width or columns == 1:\",\"            chosen_columns = columns\",\"            chosen_rows = rows\",\"            chosen_widths = widths\",\"            break\",\"\",\"    lines: list[str] = []\",\"    for row in range(chosen_rows):\",\"        row_cells: list[tuple[int, str]] = []\",\"        for column in range(chosen_columns):\",\"            index = row * chosen_columns + column if across else row + column * chosen_rows\",\"            if index < count:\",\"                row_cells.append((column, cells[index]))\",\"        bits: list[str] = []\",\"        for position, (column, cell) in enumerate(row_cells):\",\"            bits.append(cell)\",\"            if position != len(row_cells) - 1:\",\"                bits.append(\\\" \\\" * (chosen_widths[column] - display_width(cell) + spacing))\",\"        lines.append(\\\"\\\".join(bits))\",\"    return \\\"\\\".join(line + \\\"\\\\n\\\" for line in lines)\",\"\",\"\