.east_asian_width(char) in (\"W\", \"F\") else 1\n+    return width\n+\n+\n+def _escape(value: str) -> str:\n+    result: list[str] = []\n+    for char in value:\n+        code = ord(char)\n+        if code >= 0x20 and code != 0x7F:\n+            result.append(char)\n+        elif char == \"\\n\":\n+            result.append(\"\\\\n\")\n+        elif char == \"\\r\":\n+            result.append(\"\\\\r\")\n+        elif char == \"\\t\":\n+            result.append(\"\\\\t\")\n+        elif char == \"\\0\":\n+            result.append(\"\\\\0\")\n+        else:\n+            result.append(f\"\\\\u{{{code:x}}}\")\n+    return \"\".join(result)\n+\n+\n+def _quote(value: str, enabled: bool) -> str:\n+    value = _escape(value)\n+    if not enabled or (\" \" not in value and \"'\" not in value):\n+        return value\n+    quote = '\"' if \"'\" in value else \"'\"\n+    return f\"{quote}{value}{quote}\"\n+\n+\n+def _direct_display(entry: Entry, options: Options) -> str:\n+    if options.absolute == \"on\":\n+        return os.path.normpath(os.path.abspath(entry.path))\n+    if options.absolute == \"follow\":\n+        return os.path.realpath(entry.path)\n+    if entry.parented:\n+        return entry.name\n+    return entry.raw_path\n+\n+\n+def _classify(entry: Entry) -> str:\n+    if entry.is_dir:\n+        return \"/\"\n+    if entry.is_link:\n+        return \"@\"\n+    return \"\"\n+\n+\n+def render_name(entry: Entry, options: Options, *, link_paths: bool) -> str:\n+    name = _quote(_direct_display(entry, options), options.quote)\n+    classify = options.classify == \"always\" or (\n+        options.classify == \"auto\" and options.width is not None\n+    )\n+    if link_paths and entry.is_link and not options.dereference:\n+        try:\n+            target = os.readlink(entry.path)\n+        except OSError:\n+            target = None\n+        if target is not None:\n+            rendered_target = _quote(target, options.quote)\n+            if classify:\n+      