* chosen_rows\n+            if index < count:\n+                row_cells.append((column, cells[index]))\n+        bits: list[str] = []\n+        for position, (column, cell) in enumerate(row_cells):\n+            bits.append(cell)\n+            if position != len(row_cells) - 1:\n+                bits.append(\" \" * (chosen_widths[column] - display_width(cell) + spacing))\n+        lines.append(\"\".join(bits))\n+    return \"\".join(line + \"\\n\" for line in lines)\n+\n+\n+def render_grid(entries: list[Entry], options: Options) -> str:\n+    entries = sort_entries(entries, options)\n+    cells = [render_name(entry, options, link_paths=False) for entry in entries]\n+    return _grid_layout(cells, options.width or 80, options.across)\n+\n+\n+def _mode(entry: Entry) -> str:\n+    attributes = entry.attributes\n+    if attributes & FILE_ATTRIBUTE_REPARSE_POINT:\n+        kind = \"l\"\n+    elif attributes & FILE_ATTRIBUTE_DIRECTORY:\n+        kind = \"d\"\n+    else:\n+        kind = \"-\"\n+    return kind + \"\".join(\n+        (\n+            \"a\" if attributes & FILE_ATTRIBUTE_ARCHIVE else \"-\",\n+            \"r\" if attributes & FILE_ATTRIBUTE_READONLY else \"-\",\n+            \"h\" if attributes & FILE_ATTRIBUTE_HIDDEN else \"-\",\n+            \"s\" if attributes & FILE_ATTRIBUTE_SYSTEM else \"-\",\n+        )\n+    )\n+\n+\n+def _size(entry: Entry, options: Options) -> str:\n+    if entry.is_dir:\n+        return \"-\"\n+    size = entry.length\n+    if options.size_format == \"bytes\":\n+        return f\"{size:,}\"\n+    base = 1024 if options.size_format == \"binary\" else 1000\n+    symbols = (\"\", \"Ki\", \"Mi\", \"Gi\", \"Ti\", \"Pi\", \"Ei\") if base == 1024 else (\"\", \"k\", \"M\", \"G\", \"T\", \"P\", \"E\")\n+    power = 0\n+    number = float(size)\n+    while number >= base and power < len(symbols) - 1:\n+        number /= base\n+        power += 1\n+    if power == 0:\n+        return f\"{size:,}\"\n+    rendered = f\"{number:.1f}\" if number < 10 else str(int(math.floor(number + 0.5)))\n+    return rendered + symbols[power]\n+\n+\n+def _strftime_custom(moment: datetime, fmt: str) -> str:\n+    replacements = {\n+        \"%_d\": f\"{moment.day:2d}\",\n+        \"%e\": f\"{moment.day:2d}\",\n+        \"%s\": str(int(moment.timestamp())),\n+    }\n+    marker = fmt\n+    for source, target in replacements.items():\n+        marker = marker.replace(source, target)\n+    return moment.strftime(marker)\n+\n+\n+def _relative(seconds: float) -> str:\n+    elapsed = max(0, int(datetime.now().timestamp() - seconds))\n+    units = ((31_536_000, \"year\"), (2_592_000, \"month\"), (604_800, \"week\"), (86_400, \"day\"), (3_600, \"hour\"), (60, \"minute\"))\n+    for scale, label in units:\n+        if elapsed >= scale:\n+            value = elapsed // scale\n+            return f\"{value} {label}{'' if value == 1 else 's'}\"\n+    return \"now\"\n+\n+\n+def _time(entry: Entry, kind: str, style: str) -> str:\n+    seconds = entry.timestamp(kind)\n+    if seconds is None:\n+        return \"-\"\n+    moment = datetime.fromtimestamp(seconds).astimezone()\n+    current_year = datetime.now().year\n+    if style == \"default\":\n+        month = MONTHS[moment.month - 1]\n+        return (\n+            f\"{moment.day:2d} {month} {moment:%H:%M}\"\n+            if moment.year == current_year\n+            else f\"{moment.day:2d} {month}  {moment.year:04d}\"\n+        )\n+    if style == \"iso\":\n+        return moment.strftime(\"%m-%d %H:%M\" if moment.year == current_year else \"%Y-%m-%d\")\n+    if style == \"long-iso\":\n+        return moment.strftime(\"%Y-%m-%d %H:%M\")\n+    if style == \"full-iso\":\n+        nanoseconds = int(seconds * 1_000_000_000) % 1_000_000_000\n+        return moment.strftime(\"%Y-%m-%d %H:%M:%S\") + f\".{nanoseconds:09d} \" + moment.strftime(\"%z\")\n+    if style == \"relative\":\n+        return _relative(seconds)\n+    if style.startswith(\"+\"):\n+        formats = style[1:].splitlines()\n+        if not formats or not formats[0]:\n+            return \"\"\n+        fmt = formats[1] if len(formats) > 1 and moment.year == current_year else formats[0]\n+        return _strftime_custom(moment, fmt)\n+    return \"-\"\n+\n+\n+@dataclass\n+class TreeRow:\n+    entry: Entry\n+    branches: tuple[bool, ...]\n+\n+    @property\n+    def prefix(self) -> str:\n+        if not self.branches:\n+            return \"\"\n+        bits = [\"    \" if last else \"│   \" for last in self.branches[:-1]]\n+        bits.append(\"└── \" if self.branches[-1] else \"├── \")\n+        return \"\".join(bits)\n+\n+\n+def _tree_rows(entries: list[Entry], options: Options) -> list[TreeRow]:\n+    rows: list[TreeRow] = []\n+    roots = sort_entries(entries, options)\n+\n+    def add(entry: Entry, branches: tuple[bool, ...], depth: int) -> None:\n+        rows.append(TreeRow(entry, branches))\n+        if not entry.is_dir and not (options.follow_symlinks and entry.points_to_directory):\n+            return\n+        if options.max_depth is not None and options.max_depth <= depth:\n+            return\n+        try:\n+            children = read_directory(entry.path, options)\n+        except OSError:\n+            return\n+        children = filter_children(children, options, True)\n+        for index, child in enumerate(children):\n+            add(child, (*branches, index == len(children) - 1), depth + 1)\n+\n+    for root in roots:\n+        add(root, (), 0)\n+    return rows\n+\n+\n+def _columns(options: Options) -> list[tuple[str, str, str]]:\n+    columns: list[tuple[str, str, str]] = []\n+    if options.permissions:\n+        columns.append((\"mode\", \"Mode\", \"left\"))\n+    if options.filesize:\n+        columns.append((\"size\", \"Size\", \"right\"))\n+    if options.file_flags:\n+        columns.append((\"flags\", \"Flags\", \"left\"))\n+    headers = {\n+        \"modified\": \"Date Modified\", \"changed\": \"Date Changed\",\n+        \"created\": \"Date Created\", \"accessed\": \"Date Accessed\",\n+    }\n+    columns.extend((kind, headers[kind], \"left\") for kind in options.time_types)\n+    return columns\n+\n+\n+def _cell(entry: Entry, column: str, options: Options) -> str:\n+    if column == \"mode\":\n+        return _mode(entry)\n+    if column == \"size\":\n+        return _size(entry, options)\n+    if column == \"flags\":\n+        return \"-\"\n+    return _time(entry, column, options.time_style)\n+\n+\n+def render_details(entries: list[Entry], options: Options) -> str:\n+    rows = _tree_rows(entries, options) if options.tree else [\n+        TreeRow(entry, ()) for entry in sort_entries(entries, options)\n+    ]\n+    columns = _columns(options)\n+    values = [[_cell(row.entry, column, options) for column, _, _ in columns] for row in rows]\n+    widths = [0] * len(columns)\n+    for index, (_, header, _) in enumerate(columns):\n+        if options.header:\n+            widths[index] = display_width(header)\n+        for row_values in values:\n+            widths[index] = max(widths[index], display_width(row_values[index]))\n+\n+    def metadata(cells: list[str]) -> str:\n+        bits: list[str] = []\n+        for index, cell in enumerate(cells):\n+            alignment = columns[index][2]\n+            padding = widths[index] - display_width(cell)\n+            bits.append((\" \" * padding + cell) if alignment == \"right\" else (cell + \" \" * padding))\n+            bits.append(\" \")\n+        return \"\".join(bits)\n+\n+    output: list[str] = []\n+    if options.header:\n+        output.append(metadata([header for _, header, _ in columns]) + \"Name\\n\")\n+    for row, cells in zip(rows, values):\n+        output.append(\n+            metadata(cells)\n+            + row.prefix\n+            + render_name(row.entry, options, link_paths=True)\n+            + \"\\n\"\n+        )\n+    return \"\".join(output)\n+\n+\n+def render_grid_details(entries: list[Entry], options: Options) -> str:\n+    # A redirected grid-details view has no terminal width in eza and falls\n+    # back to details. A set width uses the same table rows as grid cells.\n+    if options.width is None:\n+        return render_details(entries, options)\n+    sorted_entries = sort_entries(entries, options)\n+    columns = _columns(options)\n+    values = [[_cell(entry, column, options) for column, _, _ in columns] for entry in sorted_entries]\n+    widths = [max([display_width(header)] + [display_width(row[i]) for row in values]) for i, (_, header, _) in enumerate(columns)]\n+    cells: list[str] = []\n+    for entry, row in zip(sorted_entries, values):\n+        bits: list[str] = []\n+        for index, value in enumerate(row):\n+            padding = widths[index] - display_width(value)\n+            bits.append((\" \" * padding + value) if columns[index][2] == \"right\" else value + \" \" * padding)\n+            bits.append(\" \")\n+        bits.append(\" \")\n+        bits.append(render_name(entry, options, link_paths=False))\n+        cells.append(\"\".join(bits))\n+    return _grid_layout(cells, options.width, False, spacing=4)\n+\n+\n+def render_entries(entries: list[Entry], options: Options) -> str:\n+    if not entries:\n+        return \"\"\n+    if options.recurse and options.only_files and not options.tree:\n+        entries = [entry for entry in entries if not entry.is_dir]\n+        if not entries:\n+            return \"\"\n+    if options.view == \"lines\":\n+        return render_lines(entries, options)\n+    if options.view == \"grid\":\n+        return render_grid(entries, options)\n+    if options.view == \"grid-details\":\n+        return render_grid_details(entries, options)\n+    return render_details(entries, options)\n*** End Patch","command_type":"apply_patch","id":"runtime-18c30aa4a8787bd8.tool.command_run:call_H3XxkqU5eoFdjbaalT9AFMGI:3","provider_tool_call_id":"call_H3XxkqU5eoFdjbaalT9AFMGI","status":"completed","step":1,"type":"file_change"},"type":"item.completed"}
