pos                list root of git-tree status\n+  --git-repos-no-status      list each git-repos branch name (much faster)\n+    \n+\"\"\"\n+\n+\n+def _write_stdout(value: str) -> None:\n+    sys.stdout.buffer.write(value.encode(\"utf-8\", errors=\"replace\"))\n+\n+\n+def _write_stderr(value: str) -> None:\n+    sys.stderr.buffer.write(value.encode(\"utf-8\", errors=\"replace\"))\n+\n+\n+def _debug_path(value: str) -> str:\n+    return json.dumps(value, ensure_ascii=False)\n+\n+\n+def _os_error(error: OSError) -> str:\n+    code = error.winerror if getattr(error, \"winerror\", None) is not None else error.errno\n+    windows_messages = {\n+        2: \"The system cannot find the file specified.\",\n+        3: \"The system cannot find the path specified.\",\n+        5: \"Access is denied.\",\n+        13: \"Permission denied\",\n+    }\n+    message = windows_messages.get(code, error.strerror or str(error))\n+    return f\"{message} (os error {code})\" if code is not None else message\n+\n+\n+class Application:\n+    def __init__(self, options: Options) -> None:\n+        self.options = options\n+        self.stdout: list[str] = []\n+        self.stderr: list[str] = []\n+        self.status = 0\n+\n+    def run(self) -> int:\n+        paths = list(self.options.paths)\n+        if not paths:\n+            if self.options.stdin_mode:\n+                text = sys.stdin.buffer.read().decode(\"utf-8\")\n+                paths = [item for item in text.split(self.options.stdin_separator) if item]\n+            else:\n+                paths = [\".\"]\n+\n+        files: list[Entry] = []\n+        directories: list[Entry] = []\n+        for raw_path in paths:\n+            try:\n+                entry = Entry.direct(raw_path, self.options.dereference)\n+            except OSError as error:\n+                self.status = 2\n+                self.stderr.append(f\"{_debug_path(raw_path)}: {_os_error(error)}\\n\")\n+                continue\n+            if entry.points_to_directory and not self.options.treat_dirs_as_files:\n+                directories.append(entry)\n+            else:\n+                files.append(entry)\n+\n+        no_files = not files\n+        only_directory = len(directories) == 1 and no_files\n+        files = filter_argument_entries(files, self.options)\n+        self.stdout.append(render_entries(files, self.options))\n+        self._print_directories(directories, no_files, only_directory)\n+        _write_stdout(\"\".join(self.stdout))\n+        _write_stderr(\"\".join(self.stderr))\n+        return self.status\n+\n+    def _print_directories(\n+        self,\n+        directories: list[Entry],\n+        first: bool,\n+        only_directory: bool,\n+    ) -> None:\n+        for directory in directories:\n+            try:\n+                children = read_directory(directory.path, self.options)\n+            except PermissionError:\n+                self.stderr.append(\n+                    f\"Permission denied: {directory.raw_path} - code: 13\\n\"\n+                )\n+                continue\n+            except OSError as error:\n+                self.stderr.append(f\"{directory.raw_path}: {_os_error(error)}\\n\")\n+                continue\n+\n+            if first:\n+                first = False\n+            else:\n+                self.stdout.append(\"\\n\")\n+            if not only_directory:\n+                self.stdout.append(f\"{directory.raw_path}:\\n\")\n+\n+            if self.options.recurse and not self.options.tree and not self._too_deep(directory.path):\n+                child_directories = [\n+                    entry for entry in children\n+                    if (\n+                        entry.points_to_directory\n+                        if self.options.follow_symlinks\n+                        else entry.is_dir\n+                    )\n+                    and not entry.is_all_all\n+                ]\n+                self.stdout.append(render_entries(children, self.options))\n+                self._print_directories(child_directories, False, False)\n+            else:\n+                self.stdout.append(render_entries(children, self.options))\n+\n+    def _too_deep(self, path: Path) -> bool:\n+        if self.options.max_depth is None:\n+            return False\n+        components = [part for part in path.parts if part != \".\"]\n+        return self.options.max_depth <= len(components) + 1\n+\n+\n+def main(argv: Sequence[str] | None = None) -> int:\n+    arguments = list(sys.argv[1:] if argv is None else argv)\n+    try:\n+        options = deduce_options(\n+            arguments,\n+            os.environ,\n+            stdout_isatty=sys.stdout.isatty(),\n+            stdin_isatty=sys.stdin.isatty(),\n+        )\n+    except OptionError as error:\n+        _write_stderr(f\"eza: {error}\\n\")\n+        return 3\n+\n+    if options.special == \"help\":\n+        _write_stdout(HELP)\n+        return 0\n+    if options.special == \"version\":\n+        _write_stdout(VERSION)\n+        return 0\n+    return Application(options).run()\n+\n+\n+if __name__ == \"__main__\":\n+    raise SystemExit(main())\n*** End Patch","command_type":"apply_patch","id":"runtime-18c30aa4a8787bd8.tool.command_run:call_H3XxkqU5eoFdjbaalT9AFMGI:4","provider_tool_call_id":"call_H3XxkqU5eoFdjbaalT9AFMGI","status":"completed","step":1,"type":"file_change"},"type":"item.completed"}
