ead_bytes()\n+        expected_stderr = (SNAPSHOT_ROOT / f\"{stem}.stderr\").read_bytes()\n+        if (\n+            completed.returncode == expected_status\n+            and completed.stdout == expected_stdout\n+            and completed.stderr == expected_stderr\n+        ):\n+            print(f\"PASS {stem}\")\n+            continue\n+\n+        failures += 1\n+        print(f\"FAIL {stem}\")\n+        if completed.returncode != expected_status:\n+            print(\n+                f\"  status expected={expected_status} \"\n+                f\"actual={completed.returncode}\"\n+            )\n+        if completed.stdout != expected_stdout:\n+            print(f\"  stdout expected={expected_stdout!r}\")\n+            print(f\"  stdout actual  ={completed.stdout!r}\")\n+        if completed.stderr != expected_stderr:\n+            print(f\"  stderr expected={expected_stderr!r}\")\n+            print(f\"  stderr actual  ={completed.stderr!r}\")\n+\n+    print(f\"{len(CASES) - failures}/{len(CASES)} original snapshots passed\")\n+    return 1 if failures else 0\n+\n+\n+if __name__ == \"__main__\":\n+    raise SystemExit(main())\n*** End Patch","command_type":"apply_patch","id":"runtime-18c30d1c3f6e9c24.tool.command_run:call_mDI6FfUjJYsy6BIKBoo1fUzs:0","provider_tool_call_id":"call_mDI6FfUjJYsy6BIKBoo1fUzs","status":"completed","step":1,"type":"file_change"},"type":"item.completed"}
